import java.io.BufferedReader; import java.io.InputStreamReader; import java.io.IOException; public class TestClass { public static void main(String[] args) throws IOException { BufferedReader br = new BufferedReader(new InputStreamReader(System.in)); String line = br.readLine(); if (line != null && !line.isEmpty()) { int n = Integer.parseInt(line.trim()); for (int i = 0; i < n; i++) { String input = br.readLine(); if (input != null) { System.out.println(input); } } } } }